// restricted_note row-level security — generated by `pnpm gen:migration` (02-architecture §4, 04-testing §3);
// D-28 readers (Sales owner, assigned PM, director, sponsor) and E2 AC7 cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  eq,
  inActorTransaction,
  migrateUp,
  restrictedNote,
  site,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const siteA = randomUUID();
const siteB = randomUUID();
const staffOf = (...roles: string[]): DbActor => ({ id: randomUUID(), kind: 'staff', clientIds: [], roles });
const salesOwner = staffOf('sales');
const pm = staffOf('pm');
const director = staffOf('director');
const sponsor = staffOf('sponsor');
const otherSales = staffOf('sales');
const otherPm = staffOf('pm');
const admin = staffOf('admin');
const system: DbActor = { id: randomUUID(), kind: 'system', clientIds: [], roles: ['system'] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, runningNo: number) => ({
  id,
  clientId: clientA,
  projectId: `CLIENTA-ES-MAD-00${String(runningNo)}`,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo,
  name: `Site 00${String(runningNo)}`,
  standard: 'S' as const,
  salesOwnerId: salesOwner.id,
  pmId: runningNo === 1 ? pm.id : null,
});
const noteBy = (author: DbActor, siteId = siteA) => ({
  id: randomUUID(),
  clientId: clientA,
  siteId,
  itemCode: 'F1',
  body: 'Promised a second calibration visit at no cost',
  authorId: author.id,
});
let testDb: TestDatabase;
let database: Database;

const notesSeenBy = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) => (await tx.select().from(restrictedNote)).length);
const write = (actor: DbActor, note: ReturnType<typeof noteBy>) =>
  inActorTransaction(database.db, actor, (tx) => tx.insert(restrictedNote).values(note));

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await inActorTransaction(database.db, director, async (tx) => {
    await tx.insert(client).values({ id: clientA, shortCode: 'CLIENTA', name: 'Client A' });
    await tx.insert(site).values([siteOf(siteA, 1), siteOf(siteB, 2)]);
  });
  await write(salesOwner, noteBy(salesOwner));
  await write(director, noteBy(director, siteB));
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it("the project's Sales owner and PM, the director and the sponsor read the notes (D-28)", async () => {
  expect(await notesSeenBy(salesOwner)).toBe(2); // Sales owner of both projects
  expect(await notesSeenBy(pm)).toBe(1); // PM of project 1 only
  expect(await notesSeenBy(director)).toBe(2);
  expect(await notesSeenBy(sponsor)).toBe(2);
});

it('other staff, the system actor (AI, MCP), clients and partners read nothing', async () => {
  for (const actor of [otherSales, otherPm, admin, system, userOfA, partnerOfA]) {
    expect(await notesSeenBy(actor)).toBe(0);
  }
});

it('only readers write, and only as themselves', async () => {
  await write(pm, noteBy(pm));
  await expect(write(otherPm, noteBy(otherPm))).rejects.toThrow();
  await expect(write(system, noteBy(system))).rejects.toThrow();
  await expect(write(pm, noteBy(salesOwner))).rejects.toThrow();
  await expect(write(pm, noteBy(pm, siteB))).rejects.toThrow();
});

it('a note is never edited, only archived', async () => {
  await expect(
    inActorTransaction(database.db, salesOwner, (tx) =>
      tx.update(restrictedNote).set({ body: 'Changed' }).where(eq(restrictedNote.siteId, siteA)),
    ),
  ).rejects.toThrow();
  await inActorTransaction(database.db, salesOwner, (tx) =>
    tx.update(restrictedNote).set({ archivedAt: new Date() }).where(eq(restrictedNote.siteId, siteA)),
  );
});

it('a note has content and cites a group F item when it records one', async () => {
  await expect(write(director, { ...noteBy(director), body: ' ' })).rejects.toThrow();
  await expect(write(director, { ...noteBy(director), itemCode: 'A1' })).rejects.toThrow();
});

it("a reader's AI agent via MCP adds notes but never reads or archives them (D-28, 08-ai-and-mcp)", async () => {
  const salesOwnerViaMcp: DbActor = { ...salesOwner, via: 'mcp:claude' };
  expect(await notesSeenBy(salesOwnerViaMcp)).toBe(0);
  await write(salesOwnerViaMcp, noteBy(salesOwner));
  const archivedViaMcp = await inActorTransaction(database.db, salesOwnerViaMcp, (tx) =>
    tx
      .update(restrictedNote)
      .set({ archivedAt: new Date() })
      .where(eq(restrictedNote.siteId, siteB))
      .returning({ id: restrictedNote.id }),
  ).catch(() => []);
  expect(archivedViaMcp).toEqual([]);
  // The note written via MCP is there for the person, read directly.
  expect(await notesSeenBy(salesOwner)).toBeGreaterThanOrEqual(3);
});
